                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        q = (y + dy, x + dx)
                        if (0 <= q[0] < h and 0 <= q[1] < w
                                and q not in seen and grid[q[0]][q[1]] == color):
                            seen.add(q)
                            stack.append(q)
            if color == 8:
                fixed.update(cells)
            else:
                objects.append((color, cells))

    # Place rightmost objects first; each slides right until blocked by
    # the border, a fixed 8, or an object already placed.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    out = [[0] * w for _ in range(h)]
    occupied = set(fixed)

    for r, c in fixed:
        out[r][c] = 8

    for color, cells in objects:
        shift = 0
